initial.css:
:root { --ground: #FAFBFC; --panel: #FFFFFF; --ink: #1B232C; --ink-2: #5A6672; --line: #DDE3E9; --hard: #C62828; --hard-bg: #FBEAEA; --soft: #D97706; --soft-bg: #FBF1E3; --clean: #2E7D32; --clean-bg: #E9F3EA; --live: #0E7490; --live-bg: #E3F1F5; --chrome: #EEF1F4; --code-bg: #141A20; --code-ink: #D7E0E8; }
@media (prefers-color-scheme: dark) {
  :root { --ground: #10151A; --panel: #171E25; --ink: #E8EDF2; --ink-2: #8B98A5; --line: #2A343E; --hard: #EF6B60; --hard-bg: #2A1A18; --soft: #E5A44E; --soft-bg: #291F10; --clean: #7CBF81; --clean-bg: #16221A; --live: #4FB3CC; --live-bg: #0F2229; --chrome: #0B0F13; --code-bg: #0B0F13; --code-ink: #C6D2DC; }
}
:root[data-theme="light"] { --ground: #FAFBFC; --panel: #FFFFFF; --ink: #1B232C; --ink-2: #5A6672; --line: #DDE3E9; --hard: #C62828; --hard-bg: #FBEAEA; --soft: #D97706; --soft-bg: #FBF1E3; --clean: #2E7D32; --clean-bg: #E9F3EA; --live: #0E7490; --live-bg: #E3F1F5; --chrome: #EEF1F4; --code-bg: #141A20; --code-ink: #D7E0E8; }
:root[data-theme="dark"] { --ground: #10151A; --panel: #171E25; --ink: #E8EDF2; --ink-2: #8B98A5; --line: #2A343E; --hard: #EF6B60; --hard-bg: #2A1A18; --soft: #E5A44E; --soft-bg: #291F10; --clean: #7CBF81; --clean-bg: #16221A; --live: #4FB3CC; --live-bg: #0F2229; --chrome: #0B0F13; --code-bg: #0B0F13; --code-ink: #C6D2DC; }
* { box-sizing: border-box; }
body { margin: 0px; background: var(--ground); color: var(--ink); font: 16px / 1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
.mono, code, .chip, .eyebrow, .check li, .topbar { font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; }
.topbar { display: flex; gap: 18px; align-items: baseline; flex-wrap: wrap; padding: 14px 24px; border-bottom: 1px solid var(--line); font-size: 13px; }
.topbar .brand { font-weight: 700; letter-spacing: 0.04em; }
.topbar .pid { color: var(--ink-2); }
.topbar .act { margin-left: auto; color: var(--ink-2); }
.rec { color: var(--live); }
.rec .dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--live); margin-right: 5px; animation: 1.6s ease 0s infinite normal none running pulse; }
@keyframes pulse { 
  50% { opacity: 0.25; }
}
@media (prefers-reduced-motion: reduce) {
  .rec .dot { animation: auto ease 0s 1 normal none running none; }
}
.cols { display: grid; grid-template-columns: minmax(0px, 1fr) 292px; gap: 28px; max-width: 1060px; margin: 0px auto; padding: 28px 24px 64px; }
@media (max-width: 820px) {
  .cols { grid-template-columns: 1fr; }
}
main { min-width: 0px; }
.view { display: none; }
.view.active { display: block; }
.eyebrow { font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-2); margin: 0px 0px 6px; }
.eyebrow .act2 { color: var(--hard); }
h2 { font-size: 26px; line-height: 1.2; margin: 0px 0px 12px; text-wrap: balance; }
.stepcopy { max-width: 62ch; color: var(--ink); margin: 0px 0px 20px; }
.stepcopy em { color: var(--ink-2); font-style: normal; }
.task { background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 20px; margin: 0px 0px 18px; }
.task .label { font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-2); margin: 0px 0px 10px; }
.rule { padding: 14px 16px; border-left: 3px solid var(--soft); background: var(--soft-bg); border-radius: 0px 4px 4px 0px; margin: 0px 0px 14px; font-size: 15px; }
textarea { width: 100%; min-height: 74px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 4px; background: var(--ground); color: var(--ink); font: inherit; resize: vertical; }
.btnrow { display: flex; gap: 10px; margin-top: 14px; }
.btn { padding: 9px 18px; border-radius: 4px; border: 1px solid var(--line); background: var(--panel); color: var(--ink); cursor: pointer; }
.btn.primary { background: var(--ink); color: var(--ground); border-color: var(--ink); }
.expect { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; background: var(--panel); border: 1px dashed var(--line); border-radius: 4px; font-size: 14px; color: var(--ink-2); }
.expect b { color: var(--ink); }
.expect .tag { flex: 0 0 auto; font-size: 11px; letter-spacing: 0.1em; color: var(--live); text-transform: uppercase; padding-top: 2px; }
.violations { display: flex; gap: 8px; flex-wrap: wrap; margin: 0px 0px 14px; }
.chip { font-size: 12px; padding: 4px 10px; border-radius: 99px; border: 1px solid var(--line); }
.chip.hot { background: var(--hard-bg); color: var(--hard); border-color: transparent; }
.scramble { position: relative; user-select: none; }
.scramble .content { filter: blur(6px); opacity: 0.7; }
.scramble .banner { position: absolute; inset: 0px; display: flex; align-items: center; justify-content: center; }
.scramble .banner span { background: var(--hard); color: rgb(255, 255, 255); font: 700 12px / 1 ui-monospace, Menlo, monospace; letter-spacing: 0.12em; padding: 8px 14px; border-radius: 3px; }
.files { display: flex; gap: 10px; flex-wrap: wrap; margin: 0px 0px 14px; }
.file { display: flex; flex-direction: column; gap: 10px; min-width: 190px; border: 1px solid var(--line); background: var(--panel); border-radius: 4px; padding: 10px 14px; font: 13px / 1.4 ui-monospace, Menlo, monospace; }
.file small { display: block; color: var(--ink-2); font-size: 11px; }
.file .file-desc { display: block; color: var(--ink-2); font-size: 11px; }
.file .file-actions { display: flex; gap: 12px; align-items: center; }
.file .file-actions a { color: var(--live); font-size: 12px; }
pre { background: var(--code-bg); color: var(--code-ink); padding: 14px 16px; border-radius: 4px; overflow-x: auto; font-size: 13.5px; margin: 0px 0px 18px; }
.yourreport { border-left: 3px solid var(--live); padding: 2px 0px 2px 16px; margin: 0px 0px 18px; }
.yourreport li { margin: 0px 0px 8px; max-width: 60ch; }
.yourreport .t-hard { color: var(--hard); font-weight: 700; }
.yourreport .t-soft { color: var(--soft); font-weight: 700; }
.yourreport .t-clean { color: var(--clean); font-weight: 700; }
aside { position: sticky; top: 20px; align-self: start; background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 16px 16px 12px; }
aside h3 { margin: 0px 0px 2px; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-2); }
aside .sub { font-size: 12px; color: var(--ink-2); margin: 0px 0px 12px; }
.check { list-style: none; margin: 0px; padding: 0px; font-size: 13px; max-height: calc(-180px + 100vh); overflow-y: auto; }
.check li { display: flex; align-items: center; gap: 8px; padding: 5px 0px; border-bottom: 1px solid var(--line); color: var(--ink-2); }
.check li:last-child { border-bottom: 0px; }
.check .lamp { flex: 0 0 auto; width: 9px; height: 9px; border-radius: 50%; background: transparent; border: 1.5px solid var(--line); }
.check li.lit { color: var(--ink); }
.check li.lit .lamp { background: var(--clean); border-color: var(--clean); }
.check li.lit.hardlit .lamp { background: var(--hard); border-color: var(--hard); }
.check li .n { margin-left: auto; color: var(--ink-2); font-size: 12px; }
.check li.always .lamp { background: var(--line); border-color: var(--line); }
.check .hint { font-size: 11.5px; color: var(--ink-2); padding: 8px 0px 2px; border-bottom: 0px; }
body[data-view="act2"] .check li.guardrow { color: var(--hard); }
body[data-view="act2"] .check li.guardrow .lamp { background: var(--hard); border-color: var(--hard); }
@keyframes lamp-pulse { 
  0% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.8); opacity: 0.4; }
  100% { transform: scale(1); opacity: 1; }
}
.check .lamp.lamp-pulse { animation: 0.6s ease-out 0s 1 normal none running lamp-pulse; }
@media (prefers-reduced-motion: reduce) {
  .check .lamp.lamp-pulse { animation: auto ease 0s 1 normal none running none; }
}
.results-mode main { grid-column: 1 / -1; }
.finale-mount { min-height: 100px; border: 1px solid var(--line); border-radius: 4px; padding: 16px; margin: 0px 0px 12px; background: var(--panel); }
.results-frame { width: 100%; min-height: 70vh; border: 1px solid var(--line); border-radius: 4px; background: rgb(255, 255, 255); }
button:focus-visible, a:focus-visible { outline: 2px solid var(--live); outline-offset: 2px; }
.filetext-dialog { max-width: 640px; width: 90vw; padding: 18px; border: 1px solid var(--line); border-radius: 4px; background: var(--panel); color: var(--ink); }
.filetext-dialog::backdrop { background: rgba(0, 0, 0, 0.4); }
.filetext-dialog h3 { margin: 0px 0px 10px; font: 600 13px / 1 ui-monospace, Menlo, monospace; }
.filetext-dialog pre { max-height: 60vh; overflow: auto; user-select: text; margin: 0px 0px 14px; }
